div.script:

(function () {

  let globalIndex = 0;
  let certCacheByRole = {};

  function setRequired(el, isReq) {
    if (!el) return;
    if (isReq) el.setAttribute("required", "required");
    else el.removeAttribute("required");
  }

  function showAlert(msg) {
    const alertBox = document.getElementById("formAlert");
    const alertText = document.getElementById("formAlertText");
    if (!alertBox || !alertText) return;
    alertText.textContent = msg;
    alertBox.classList.remove("d-none");
    alertBox.scrollIntoView({ behavior: "smooth", block: "start" });
  }

  function clearAlert() {
    const alertBox = document.getElementById("formAlert");
    const alertText = document.getElementById("formAlertText");
    if (!alertBox || !alertText) return;
    alertText.textContent = "";
    alertBox.classList.add("d-none");
  }

  async function fetchCerts(role) {
    if (certCacheByRole[role]) return certCacheByRole[role];

    const payload = {
      jsonrpc: "2.0",
      method: "call",
      params: { role: role },
      id: Date.now(),
    };

    const r = await fetch("/register/certificates", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(payload),
      credentials: "same-origin",
    });

    const data = await r.json();
    if (data.error) {
      throw new Error(data.error.data?.message || data.error.message || "Error RPC");
    }

    const res = data.result || [];
    certCacheByRole[role] = res;
    return res;
  }

  // Todo valor que viene del servidor se escapa antes de entrar en HTML:
  // nombre y emisor del certificado los edita un administrador, y un
  // nombre con "<img onerror=...>" se ejecutaba en el registro público.
  function esc(v) {
    return String(v == null ? "" : v)
      .replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;").replace(/'/g, "&#39;");
  }

  function buildOptions(certs) {
    const out = ['<option value="">Seleccione…</option>'];
    certs.forEach(c => {
      const val = c.ref || c.uuid_ref || c.id;
      out.push(`<option value="${esc(val)}" data-issuer="${esc(c.issuer || "")}">${esc(c.name)}</option>`);
    });
    return out.join("");
  }

  function certCardHtml(idx, optionsHtml) {
    return `
      <div class="card border-0 shadow-sm mb-3" style="border-radius:16px; border:1px solid rgba(0,0,0,.06) !important;">
        <div class="card-body p-3">
          <div class="d-flex justify-content-between align-items-center mb-2">
            <div style="font-weight:900;">Certificado</div>
            <button type="button" class="btn btn-outline-danger btn-sm delBtn" style="border-radius:12px;">Eliminar</button>
          </div>

          <div class="row g-2">
            <div class="col-md-5">
              <label class="form-label small text-muted mb-1">Certificado</label>
              <select class="form-select form-select-sm certSel"
                      name="cert_line_${idx}_id" required style="border-radius:12px;">
                ${optionsHtml}
              </select>
            </div>

            <div class="col-md-3">
              <label class="form-label small text-muted mb-1">Entidad</label>
              <input class="form-control form-control-sm issuer" type="text" readonly
                     style="border-radius:12px;" placeholder="Entidad"/>
            </div>

            <div class="col-md-4">
              <label class="form-label small text-muted mb-1">N°</label>
              <input class="form-control form-control-sm"
                     name="cert_line_${idx}_number"
                     style="border-radius:12px;" placeholder="Opcional"/>
            </div>

            <div class="col-md-4">
              <label class="form-label small text-muted mb-1">Emisión</label>
              <input class="form-control form-control-sm" type="date"
                     name="cert_line_${idx}_issue_date"
                     style="border-radius:12px;"/>
            </div>

            <div class="col-md-4">
              <label class="form-label small text-muted mb-1">Expira</label>
              <input class="form-control form-control-sm" type="date"
                     name="cert_line_${idx}_expiry_date"
                     style="border-radius:12px;"/>
            </div>

            <div class="col-md-4">
              <label class="form-label small text-muted mb-1">Archivo</label>
              <input class="form-control form-control-sm" type="file"
                     name="cert_line_${idx}_file" required
                     style="border-radius:12px; border-style:dashed;"/>
            </div>
          </div>
        </div>
      </div>
    `;
  }

  async function addCertRow(block) {
    const role = block.getAttribute("data-role");
    const container = block.querySelector(".shrimpCertTbody");
    if (!container) return;

    const certs = await fetchCerts(role);
    const idx = globalIndex++;

    const wrapper = document.createElement("div");
    wrapper.innerHTML = certCardHtml(idx, buildOptions(certs));
    const card = wrapper.firstElementChild;
    container.appendChild(card);

    const sel = card.querySelector(".certSel");
    const issuerInp = card.querySelector(".issuer");

    sel.addEventListener("change", () => {
      const opt = sel.selectedOptions[0];
      issuerInp.value = opt ? (opt.getAttribute("data-issuer") || "") : "";
    });

    card.querySelector(".delBtn").addEventListener("click", () => card.remove());
  }

  function refreshCertTables(activeRole) {
    document.querySelectorAll(".shrimp-cert-block").forEach(block => {
      const role = block.getAttribute("data-role");
      const container = block.querySelector(".shrimpCertTbody");
      if (container) container.innerHTML = "";
      if (role === activeRole) {
        addCertRow(block);
      }
    });
  }

  function toggleSections(typeSel) {
    const secSem = document.getElementById("section_semillero");
    const secLab = document.getElementById("section_laboratorio");
    const secFarm = document.getElementById("section_camaronera");

    const labRazon = document.getElementById("lab_razon_social");
    const labUbic = document.getElementById("lab_ubicacion");
    const farmRazon = document.getElementById("farm_razon_social");
    const farmUbic = document.getElementById("farm_ubicacion");

    const labReqBadge = document.getElementById("lab_required_badge");
    const labUbicReqBadge = document.getElementById("lab_ubic_required_badge");
    const farmReqBadge = document.getElementById("farm_required_badge");
    const farmUbicReqBadge = document.getElementById("farm_ubic_required_badge");

    const pillSem = document.getElementById("pill_semillero");
    const pillLab = document.getElementById("pill_laboratorio");
    const pillFarm = document.getElementById("pill_camaronera");

    [secSem, secLab, secFarm].forEach(s => s && s.classList.add("d-none"));
    [labReqBadge, labUbicReqBadge, farmReqBadge, farmUbicReqBadge].forEach(b => b && b.classList.add("d-none"));

    setRequired(labRazon, false);
    setRequired(labUbic, false);
    setRequired(farmRazon, false);
    setRequired(farmUbic, false);

    // reset pills
    [pillSem, pillLab, pillFarm].forEach(p => {
      if (!p) return;
      p.classList.remove("text-bg-success", "text-bg-primary", "text-bg-warning");
      p.classList.add("text-bg-light", "border");
    });

    if (typeSel === "semillero") {
      secSem.classList.remove("d-none");
      if (pillSem) { pillSem.classList.remove("text-bg-light","border"); pillSem.classList.add("text-bg-success"); }
    }
    if (typeSel === "laboratorio") {
      secLab.classList.remove("d-none");
      setRequired(labRazon, true);
      setRequired(labUbic, true);
      labReqBadge && labReqBadge.classList.remove("d-none");
      labUbicReqBadge && labUbicReqBadge.classList.remove("d-none");
      if (pillLab) { pillLab.classList.remove("text-bg-light","border"); pillLab.classList.add("text-bg-primary"); }
    }
    if (typeSel === "camaronera") {
      secFarm.classList.remove("d-none");
      setRequired(farmRazon, true);
      setRequired(farmUbic, true);
      farmReqBadge && farmReqBadge.classList.remove("d-none");
      farmUbicReqBadge && farmUbicReqBadge.classList.remove("d-none");
      if (pillFarm) { pillFarm.classList.remove("text-bg-light","border"); pillFarm.classList.add("text-bg-warning"); }
    }
  }

  function init() {
    const form = document.getElementById("shrimpRegisterForm");
    const typeSel = document.getElementById("shrimp_user_type");
    const pass = document.getElementById("password");
    const pass2 = document.getElementById("password_confirm");

    if (!form || !typeSel) return false;

    document.querySelectorAll(".shrimpAddCert").forEach(btn => {
      btn.addEventListener("click", () => {
        const block = btn.closest(".shrimp-cert-block");
        if (block) addCertRow(block);
      });
    });

    typeSel.addEventListener("change", () => {
      clearAlert();
      toggleSections(typeSel.value);
      refreshCertTables(typeSel.value);
    });

    form.addEventListener("submit", function (e) {
      clearAlert();

      if (!typeSel.value) {
        e.preventDefault();
        showAlert("Selecciona el tipo de usuario.");
        return;
      }

      if (pass && pass2 && pass.value !== pass2.value) {
        e.preventDefault();
        showAlert("Las contraseñas no coinciden.");
        return;
      }

      if (!form.checkValidity()) {
        e.preventDefault();
        showAlert("Revisa los campos obligatorios del formulario.");
      }
    });

    toggleSections(typeSel.value);
    if (typeSel.value) refreshCertTables(typeSel.value);
    return true;
  }

  document.addEventListener("DOMContentLoaded", function () {
    if (init()) return;
    let tries = 0;
    const timer = setInterval(() => {
      tries++;
      if (init() || tries > 20) clearInterval(timer);
    }, 200);
  });

})();
